//! Differential replay of recorded TS write operations
//! (test/__rs/upsert/fixtures/*.jsonl.gz, generated by test/__rs/upsert/record.sh).
//!
//! For every recorded adapter operation the database is restored to the
//! recorded "before" state and the Rust operation runs with the recorded
//! operation arguments. Everything the upsert port computes itself is
//! compared with the TS recording:
//! - every `transformForWrite` call runs the real Rust
//!   `payload_sql_write::transform_for_write` on the data the Rust code built;
//!   its input data, RowToInsert / error and the mutated data are compared,
//! - `shouldUseOptimizedUpsertRow` runs on the Rust data (data + decision),
//! - every `upsertRow` call (args, data, returned value),
//! - the operation result or error, the write statements and the full table
//!   contents afterwards.
//!
//! Only the results of modules owned by other ports are taken from the
//! recording: `buildQuery` / `selectDistinct` / `findMany` /
//! `buildFindManyArgs` results and the read `transform` output. The rows the
//! read side looks up (`findFirst` in upsertRow and deleteOne) are looked up
//! in the Rust database and checked against the recorded read input.

use std::cell::RefCell;
use std::collections::{HashMap, VecDeque};
use std::path::{Path, PathBuf};

use indexmap::IndexMap;
use payload_engine::error::{EngineError, Result};
use payload_engine::js::{JsVal, Obj, decode_graph_typed};
use payload_engine::sql::schema::{RawSchema, RawTable};
use payload_sql_upsert::ops::{self, BuiltQuery, CreateVersionArgs, Env, OpsHost, UpdateOneArgs, WriteArgs};
use payload_sql_upsert::sql::{Executor, SqlFragment};
use payload_sql_upsert::{AdapterOptions, FindArgsShape, RowToInsert, UpsertHost, UpsertOutcome, UpsertRowArgs, WriteContext};
use payload_sql_write::{StaticWriteAdapter, encode_value};
use rusqlite::Connection;
use serde_json::{Map, Value as Json, json};

type Dump = Map<String, Json>;

fn decode(v: &Json) -> JsVal {
  decode_graph_typed(&json!({ "objects": [], "root": v })).expect("decodable fixture value")
}

struct Schema {
  raw: RawSchema,
  opts: AdapterOptions,
  ddl: Vec<String>,
  foreign_keys: bool,
  write_adapter: Json,
  config_blocks: JsVal,
}

fn build_schema(ev: &Json) -> Schema {
  let mut raw = RawSchema::default();
  if let Some(tables) = ev.get("rawTables").and_then(Json::as_object) {
    for (k, t) in tables {
      let obj = |key: &str| t.get(key).and_then(Json::as_object).cloned().unwrap_or_default();
      let table = t.is_object().then(|| RawTable {
        name: t.get("name").and_then(Json::as_str).unwrap_or(k).to_string(),
        columns: obj("columns"),
        foreign_keys: obj("foreignKeys"),
        indexes: obj("indexes"),
      });
      raw.raw_tables.insert(k.clone(), table);
    }
  }
  // Tables extended through before/afterSchemaInit carry extra drizzle columns: add them to the
  // raw table in drizzle column order (the integration must pass these columns the same way).
  if let Some(tc) = ev.get("tableColumns").and_then(Json::as_object) {
    for (name, cols) in tc {
      let Some(Some(t)) = raw.raw_tables.get_mut(name) else { continue };
      let cols = cols.as_array().cloned().unwrap_or_default();
      if cols.iter().all(|c| c["key"].as_str().is_some_and(|k| t.columns.contains_key(k))) {
        continue;
      }
      let mut columns = Map::new();
      for c in cols {
        let key = c["key"].as_str().unwrap_or_default().to_string();
        let column = t.columns.get(&key).cloned().unwrap_or_else(|| {
          let ty = match c["columnType"].as_str().unwrap_or("") {
            "SQLiteBoolean" => "boolean",
            "SQLiteTextJson" | "SQLiteBlobJson" => "jsonb",
            "SQLiteNumericNumber" => "numeric",
            "SQLiteText" => "varchar",
            _ => "integer",
          };
          let mut m = json!({ "name": c["name"], "type": ty });
          if let Some(d) = c.get("default").filter(|d| !d.is_null()) {
            m["default"] = decode(d).to_json();
          }
          m
        });
        columns.insert(key, column);
      }
      t.columns = columns;
    }
  }
  if let Some(fc) = ev.get("fieldConstraints").and_then(Json::as_object) {
    for (table, m) in fc {
      let inner: IndexMap<String, String> = m
        .as_object()
        .map(|m| m.iter().filter_map(|(k, v)| v.as_str().map(|s| (k.clone(), s.to_string()))).collect())
        .unwrap_or_default();
      raw.field_constraints.insert(table.clone(), inner);
    }
  }
  let write_adapter = ev.get("writeAdapter").cloned().unwrap_or(Json::Null);
  Schema {
    raw,
    opts: AdapterOptions::from_js(&JsVal::from_json(ev.get("options").unwrap_or(&Json::Null))),
    ddl: ev.get("ddl").and_then(Json::as_array).map(|a| a.iter().filter_map(|s| s.as_str().map(str::to_string)).collect()).unwrap_or_default(),
    foreign_keys: ev.get("foreignKeys").and_then(Json::as_i64).unwrap_or(0) == 1,
    config_blocks: decode(&write_adapter["configBlocks"]),
    write_adapter,
  }
}

/// The adapter state `transformForWrite` reads, with the runtime-configurable
/// `name` / `blocksAsJSON` taken from the operation's recorded transform call.
fn write_adapter(schema: &Schema, op: &Json) -> StaticWriteAdapter {
  let a = &schema.write_adapter;
  let first = op["transforms"].get(0);
  StaticWriteAdapter {
    name: first.and_then(|t| t["adapterName"].as_str()).or(a["name"].as_str()).unwrap_or("sqlite").to_string(),
    blocks_as_json: first.and_then(|t| t["blocksAsJSON"].as_bool()).or(a["blocksAsJSON"].as_bool()).unwrap_or(false),
    table_name_map: a["tableNameMap"]
      .as_object()
      .into_iter()
      .flatten()
      .map(|(k, v)| (k.clone(), v.as_str().unwrap_or_default().to_string()))
      .collect(),
    tables: a["tables"].as_object().into_iter().flatten().map(|(k, v)| (k.clone(), v.as_bool().unwrap_or(false))).collect(),
    config_blocks: schema.config_blocks.clone(),
    block_index_key: Some("__internalBlockTableNameIndex".into()),
  }
}

fn apply_diff(state: &mut Dump, diff: &Json) {
  if let Some(d) = diff.as_object() {
    for (k, v) in d {
      if v.is_null() {
        state.remove(k);
      } else {
        state.insert(k.clone(), v.clone());
      }
    }
  }
}

fn open_db(schema: &Schema) -> Connection {
  let conn = Connection::open_in_memory().expect("open sqlite");
  for stmt in schema.ddl.iter().filter(|s| !s.starts_with("CREATE TABLE sqlite_sequence")) {
    conn.execute_batch(stmt).unwrap_or_else(|e| panic!("ddl failed: {e}\n{stmt}"));
  }
  conn.execute_batch(if schema.foreign_keys { "PRAGMA foreign_keys = ON" } else { "PRAGMA foreign_keys = OFF" }).unwrap();
  conn
}

fn table_names(conn: &Connection) -> Vec<String> {
  let mut stmt = conn
    .prepare("select name from sqlite_master where type = 'table' and (name not like 'sqlite_%' or name = 'sqlite_sequence') order by name")
    .unwrap();
  stmt.query_map([], |r| r.get::<_, String>(0)).unwrap().map(|r| r.unwrap()).collect()
}

/// Same format as recorder.ts `dump`.
fn dump(conn: &Connection) -> Dump {
  let mut out = Map::new();
  for name in table_names(conn) {
    let mut cstmt = conn.prepare(&format!("select name from pragma_table_info('{name}')")).unwrap();
    let cols: Vec<String> = cstmt.query_map([], |r| r.get::<_, String>(0)).unwrap().map(|r| r.unwrap()).collect();
    if cols.is_empty() {
      continue;
    }
    let select = cols.iter().map(|c| format!("quote(\"{c}\")")).collect::<Vec<_>>().join(", ");
    let mut stmt = conn.prepare(&format!("select {select} from \"{name}\" order by rowid")).unwrap();
    let n = cols.len();
    let rows: Vec<Json> = stmt
      .query_map([], |r| {
        let mut row = vec![];
        for i in 0..n {
          let v: rusqlite::types::Value = r.get(i)?;
          row.push(Json::String(match v {
            rusqlite::types::Value::Text(s) => s,
            rusqlite::types::Value::Null => "NULL".into(),
            other => format!("{other:?}"),
          }));
        }
        Ok(Json::Array(row))
      })
      .unwrap()
      .map(|r| r.unwrap())
      .collect();
    if !rows.is_empty() {
      out.insert(name, json!({ "columns": cols, "rows": rows }));
    }
  }
  out
}

fn restore(conn: &Connection, schema: &Schema, state: &Dump) {
  conn.execute_batch("PRAGMA foreign_keys = OFF").unwrap();
  let mut sql = String::from("BEGIN;\n");
  for name in table_names(conn) {
    sql.push_str(&format!("delete from \"{name}\";\n"));
  }
  // inserting explicit ids into AUTOINCREMENT tables touches sqlite_sequence, so restore it last
  let has_sequence = table_names(conn).iter().any(|n| n == "sqlite_sequence");
  let mut entries: Vec<(&String, &Json)> = state.iter().filter(|(n, _)| n.as_str() != "sqlite_sequence").collect();
  entries.extend(state.iter().filter(|(n, _)| n.as_str() == "sqlite_sequence"));
  let mut sequence_cleared = false;
  for (name, t) in entries {
    if name.as_str() == "sqlite_sequence" {
      sql.push_str("delete from sqlite_sequence;\n");
      sequence_cleared = true;
    }
    let cols = t["columns"].as_array().unwrap();
    let cols = cols.iter().map(|c| format!("\"{}\"", c.as_str().unwrap())).collect::<Vec<_>>().join(", ");
    for row in t["rows"].as_array().unwrap() {
      let vals = row.as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect::<Vec<_>>().join(", ");
      sql.push_str(&format!("insert into \"{name}\" ({cols}) values ({vals});\n"));
    }
  }
  if has_sequence && !sequence_cleared {
    sql.push_str("delete from sqlite_sequence;\n");
  }
  sql.push_str("COMMIT;");
  conn.execute_batch(&sql).unwrap_or_else(|e| panic!("restore failed: {e}"));
  conn
    .execute_batch(if schema.foreign_keys { "PRAGMA foreign_keys = ON" } else { "PRAGMA foreign_keys = OFF" })
    .unwrap();
}

/// Ordered deep equality (key order matters, numbers compare by value).
fn first_diff(a: &Json, b: &Json, path: &str) -> Option<String> {
  match (a, b) {
    (Json::Number(x), Json::Number(y)) => (x.as_f64() != y.as_f64()).then(|| format!("{path}: {x} != {y}")),
    (Json::Object(x), Json::Object(y)) => {
      let xk: Vec<_> = x.keys().collect();
      let yk: Vec<_> = y.keys().collect();
      if xk != yk {
        return Some(format!("{path}: keys {xk:?} != {yk:?}"));
      }
      x.iter().zip(y.iter()).find_map(|((k, xv), (_, yv))| first_diff(xv, yv, &format!("{path}.{k}")))
    }
    (Json::Array(x), Json::Array(y)) => {
      if x.len() != y.len() {
        return Some(format!("{path}: len {} != {}", x.len(), y.len()));
      }
      x.iter().zip(y.iter()).enumerate().find_map(|(i, (xv, yv))| first_diff(xv, yv, &format!("{path}[{i}]")))
    }
    _ => (a != b).then(|| format!("{path}: {a} != {b}")),
  }
}

/// Counters of one boundary check kind.
#[derive(Default, Clone, Copy)]
struct Check {
  checked: usize,
  matched: usize,
}

impl Check {
  fn add(&mut self, problems: &mut Vec<String>, what: &str, diff: Option<String>) {
    self.checked += 1;
    match diff {
      None => self.matched += 1,
      Some(d) => problems.push(format!("{what}: {d}")),
    }
  }

  fn merge(&mut self, o: Check) {
    self.checked += o.checked;
    self.matched += o.matched;
  }
}

/// Replay state shared by the upsert host and the ops host.
struct State<'a> {
  op: &'a Json,
  transforms: VecDeque<&'a Json>,
  should_use: VecDeque<&'a Json>,
  upserts: VecDeque<(usize, &'a Json)>,
  reads: VecDeque<&'a Json>,
  distinct: VecDeque<Vec<JsVal>>,
  find_many: VecDeque<Vec<JsVal>>,
  current_upsert: i64,
  table_name: String,
  problems: Vec<String>,
  transform_check: Check,
  should_use_check: Check,
  upsert_check: Check,
  read_check: Check,
}

impl<'a> State<'a> {
  fn new(op: &'a Json) -> Self {
    let arr = |k: &str| op.get(k).and_then(Json::as_array).map(|a| a.iter().collect::<VecDeque<_>>()).unwrap_or_default();
    Self {
      op,
      transforms: arr("transforms"),
      should_use: arr("shouldUse"),
      upserts: arr("upserts").into_iter().enumerate().collect(),
      reads: arr("reads"),
      distinct: arr("distinct").into_iter().map(|d| d["ids"].as_array().map(|a| a.iter().map(decode).collect()).unwrap_or_default()).collect(),
      find_many: arr("findMany").into_iter().map(|d| d.as_array().map(|a| a.iter().map(decode).collect()).unwrap_or_default()).collect(),
      current_upsert: -1,
      table_name: op["args"]["tableName"].as_str().unwrap_or_default().to_string(),
      problems: vec![],
      transform_check: Check::default(),
      should_use_check: Check::default(),
      upsert_check: Check::default(),
      read_check: Check::default(),
    }
  }

  fn upsert_table(&self) -> String {
    if self.current_upsert >= 0 {
      if let Some(t) = self.op["upserts"].get(self.current_upsert as usize).and_then(|u| u["tableName"].as_str()) {
        return t.to_string();
      }
    }
    self.table_name.clone()
  }

  /// Next recorded read `transform` for the current upsert (or the op itself).
  fn next_read(&mut self, what: &str) -> Option<&'a Json> {
    let read = self.reads.pop_front();
    if read.is_none() {
      self.problems.push(format!("{what}: read transform called more often than recorded"));
    }
    read
  }
}

/// Looks up `select "id" from "<table>" where <where> limit 1` in the Rust database.
fn lookup_id(exec: &Executor<'_>, table: &str, where_: Option<&SqlFragment>) -> Result<Option<JsVal>> {
  let mut q = SqlFragment::raw(format!("select \"id\" from \"{table}\""));
  if let Some(w) = where_ {
    q.sql.push_str(" where ");
    q.sql.push_str(&w.sql);
    q.params = w.params.clone();
  }
  q.sql.push_str(" limit 1");
  let rows = exec.conn.run(&q).map_err(|e| EngineError::internal(e.into_engine_error().message))?;
  Ok(rows.into_iter().next().and_then(|row| row.into_iter().next()).map(|(_, v)| v))
}

fn result_json<T>(r: std::result::Result<T, &EngineError>, ok: impl FnOnce(T) -> Json) -> Json {
  match r {
    Ok(v) => ok(v),
    Err(e) => json!({ "error": { "name": e.name, "message": e.message } }),
  }
}

struct Host<'s, 'a> {
  st: &'s RefCell<State<'a>>,
}

impl UpsertHost for Host<'_, '_> {
  fn find_args_shape(&mut self) -> Result<FindArgsShape> {
    let st = self.st.borrow();
    let entry = st.op["findArgs"].as_array().and_then(|a| a.iter().find(|f| f["upsert"].as_i64() == Some(st.current_upsert)));
    let Some(entry) = entry else { return Ok(FindArgsShape::NeedsQuery) };
    if entry["keys"].as_array().map(|a| a.len()).unwrap_or(0) == 0 {
      return Ok(FindArgsShape::Empty);
    }
    match decode(entry.get("columns").unwrap_or(&Json::Null)) {
      JsVal::Obj(cols) if !cols.is_empty() => {
        Ok(FindArgsShape::OnlyColumns(cols.iter().filter(|(_, v)| v.truthy()).map(|(k, _)| k.clone()).collect()))
      }
      _ => Ok(FindArgsShape::NeedsQuery),
    }
  }

  fn find_first(&mut self, exec: &mut Executor<'_>, where_: &SqlFragment) -> Result<Option<JsVal>> {
    let table = self.st.borrow().upsert_table();
    // the row the read side would find, looked up in the Rust database
    let found = lookup_id(exec, &table, Some(where_))?;
    let mut st = self.st.borrow_mut();
    let Some(found) = found else { return Ok(None) };
    let Some(read) = st.next_read("findFirst") else { return Ok(None) };
    let diff = first_diff(&encode_value(&found), &read["inputID"], "findFirst id");
    let mut problems = vec![];
    st.read_check.add(&mut problems, "read", diff);
    st.problems.extend(problems);
    Ok(Some(decode(&read["output"])))
  }

  fn transform_row(&mut self, row: Obj) -> Result<JsVal> {
    let mut st = self.st.borrow_mut();
    let Some(read) = st.next_read("transform_row") else { return Ok(JsVal::Null) };
    let row = JsVal::obj(row);
    let diff = match read.get("input").filter(|v| !v.is_null()) {
      Some(input) => first_diff(&encode_value(&row), input, "returning row"),
      None => first_diff(&encode_value(row.get("id")), &read["inputID"], "returning row id"),
    };
    let mut problems = vec![];
    st.read_check.add(&mut problems, "read", diff);
    st.problems.extend(problems);
    Ok(decode(&read["output"]))
  }

  fn transform_started(&mut self, data: &JsVal, enable_atomic_writes: bool, path: &str, table_name: &str) -> Option<f64> {
    let mut st = self.st.borrow_mut();
    let Some(rec) = st.transforms.front().copied() else {
      st.problems.push("transformForWrite called more often than recorded".into());
      return None;
    };
    let mut diff = first_diff(&encode_value(data), &rec["data"], "transform input data");
    if diff.is_none() {
      let rs = json!({ "enableAtomicWrites": enable_atomic_writes, "path": path, "tableName": table_name });
      let ts = json!({ "enableAtomicWrites": rec["enableAtomicWrites"], "path": rec["path"], "tableName": rec["tableName"] });
      diff = first_diff(&rs, &ts, "transform args");
    }
    if let Some(d) = diff {
      st.problems.push(d);
    }
    rec["now"].as_f64()
  }

  fn transform_finished(&mut self, result: std::result::Result<&RowToInsert, &EngineError>, data: &JsVal) {
    let mut st = self.st.borrow_mut();
    let Some(rec) = st.transforms.pop_front() else { return };
    let rs = result_json(result, |r| r.encode());
    let ts = match rec.get("error") {
      Some(e) => json!({ "error": { "name": e["name"], "message": e["message"] } }),
      None => rec["output"].clone(),
    };
    let diff = first_diff(&rs, &ts, "RowToInsert").or_else(|| first_diff(&encode_value(data), &rec["dataAfter"], "transform dataAfter"));
    let mut problems = vec![];
    st.transform_check.add(&mut problems, "transformForWrite", diff);
    st.problems.extend(problems);
  }

  fn should_use_checked(&mut self, data: &JsVal, result: std::result::Result<bool, &EngineError>) {
    let mut st = self.st.borrow_mut();
    let Some(rec) = st.should_use.pop_front() else {
      st.problems.push("shouldUseOptimizedUpsertRow called more often than recorded".into());
      return;
    };
    let rs = json!({ "data": encode_value(data), "result": result_json(result, Json::Bool) });
    let ts_result = match rec.get("error") {
      Some(e) => json!({ "error": { "name": e["name"], "message": e["message"] } }),
      None => rec["result"].clone(),
    };
    let diff = first_diff(&rs, &json!({ "data": rec["data"], "result": ts_result }), "shouldUseOptimizedUpsertRow");
    let mut problems = vec![];
    st.should_use_check.add(&mut problems, "shouldUseOptimizedUpsertRow", diff);
    st.problems.extend(problems);
  }

  fn upsert_started(&mut self, args: &UpsertRowArgs, data: &JsVal) {
    let mut st = self.st.borrow_mut();
    let Some((index, rec)) = st.upserts.front().copied() else {
      st.problems.push("upsertRow called more often than recorded".into());
      return;
    };
    st.current_upsert = index as i64;
    let ignore = match args.ignore_result {
      payload_sql_upsert::IgnoreResult::No => json!({ "$undefined": true }),
      payload_sql_upsert::IgnoreResult::Yes => json!(true),
      payload_sql_upsert::IgnoreResult::IdOnly => json!("idOnly"),
    };
    let norm_ignore = |v: &Json| match v {
      Json::Null | Json::Bool(false) => json!({ "$undefined": true }),
      Json::Object(_) => json!({ "$undefined": true }),
      other => other.clone(),
    };
    let rs = json!({
      "tableName": args.table_name,
      "operation": args.operation.as_str(),
      "id": encode_value(&args.id),
      "customID": encode_value(&args.custom_id),
      "ignoreResult": norm_ignore(&ignore),
      "path": args.path,
      "where": args.where_.as_ref().map(|w| w.to_json()),
      "data": encode_value(data),
    });
    let ts = json!({
      "tableName": rec["tableName"],
      "operation": rec["operation"],
      "id": rec["id"],
      "customID": rec["customID"],
      "ignoreResult": norm_ignore(rec.get("ignoreResult").unwrap_or(&Json::Null)),
      "path": rec.get("path").and_then(Json::as_str).unwrap_or(""),
      "where": rec.get("where").filter(|w| w.is_object()).map(|w| json!({ "sql": w["sql"], "params": w["params"] })),
      "data": rec["data"],
    });
    if let Some(d) = first_diff(&rs, &ts, "upsertRow args") {
      st.problems.push(d);
    }
  }

  fn upsert_finished(&mut self, outcome: std::result::Result<&UpsertOutcome, &EngineError>) {
    let mut st = self.st.borrow_mut();
    let Some((_, rec)) = st.upserts.pop_front() else { return };
    let diff = match (outcome, rec.get("error")) {
      (Ok(o), None) => first_diff(&encode_value(&o.to_js()), &rec["result"], "upsertRow result"),
      (Err(_), Some(_)) => None,
      (Ok(_), Some(e)) => Some(format!("upsertRow: TS threw {} but Rust succeeded", e["message"])),
      (Err(e), None) => Some(format!("upsertRow: Rust threw {e} but TS succeeded")),
    };
    let mut problems = vec![];
    st.upsert_check.add(&mut problems, "upsertRow", diff);
    st.problems.extend(problems);
    st.current_upsert = -1;
  }
}

struct Ops<'s, 'a> {
  st: &'s RefCell<State<'a>>,
}

impl OpsHost for Ops<'_, '_> {
  fn select_distinct_ids(&mut self, _e: &mut Executor<'_>, _q: &BuiltQuery, _l: Option<i64>) -> Result<Vec<JsVal>> {
    Ok(self.st.borrow_mut().distinct.pop_front().unwrap_or_default())
  }

  fn find_many(&mut self, _e: &mut Executor<'_>) -> Result<Vec<JsVal>> {
    Ok(self.st.borrow_mut().find_many.pop_front().unwrap_or_default())
  }

  fn find_first_to_delete(&mut self, exec: &mut Executor<'_>, distinct_id: Option<&JsVal>, where_: Option<&SqlFragment>) -> Result<Option<JsVal>> {
    let table = self.st.borrow().table_name.clone();
    let by_id;
    let where_ = match distinct_id {
      Some(id) => {
        by_id = SqlFragment::new(format!("\"{table}\".\"id\" = ?"), vec![id.clone()]);
        Some(&by_id)
      }
      None => where_,
    };
    Ok(lookup_id(exec, &table, where_)?.map(|id| JsVal::obj(Obj::from([("id".to_string(), id)]))))
  }

  fn transform_doc(&mut self, doc: &JsVal) -> Result<JsVal> {
    let mut st = self.st.borrow_mut();
    let Some(read) = st.next_read("deleteOne transform") else { return Ok(JsVal::Null) };
    let diff = first_diff(&encode_value(doc.get("id")), &read["inputID"], "deleteOne doc id");
    let mut problems = vec![];
    st.read_check.add(&mut problems, "read", diff);
    st.problems.extend(problems);
    Ok(decode(&read["output"]))
  }
}

fn query_from(q: &Json) -> BuiltQuery {
  let frag = |k: &str| q.get(k).filter(|v| v.is_object()).and_then(|v| SqlFragment::from_js(&decode(v)).ok());
  BuiltQuery { where_: frag("where"), joins: q.get("joins").and_then(Json::as_u64).unwrap_or(0) as usize, order_by: frag("orderBy") }
}

/// `new Date().toISOString()` of the operation: the `createdAt` that
/// upsertRow / createGlobal put into the data of the first transform.
fn recorded_now(op: &Json) -> Option<String> {
  if op["method"] == "updateJobs" {
    return op["statements"].as_array().and_then(|st| {
      st.iter()
        .find(|s| s["sql"].as_str().is_some_and(|q| q.starts_with("update ") && q.contains("<= ?")))
        .and_then(|s| s["params"].as_array().and_then(|p| p.last()).and_then(Json::as_str).map(str::to_string))
    });
  }
  op["transforms"].get(0).and_then(|t| t["data"]["createdAt"].as_str()).map(str::to_string)
}

fn run_op(conn: &Connection, schema: &Schema, op: &Json, fields: &HashMap<i64, JsVal>, st: &RefCell<State<'_>>) -> (Result<JsVal>, Vec<Json>) {
  let args = decode(&op["args"]);
  let method = op["method"].as_str().unwrap_or_default();
  let mut exec = Executor::new(conn);
  let mut opts = schema.opts.clone();
  // adapter options can change at runtime (e.g. `payload.db.allowIDOnCreate = true`)
  if let Some(ao) = op.get("adapterOptions") {
    let ao = decode(ao);
    opts.allow_id_on_create = ao.get("allowIDOnCreate").truthy();
    opts.limited_bound_parameters = ao.get("limitedBoundParameters").truthy();
  }
  exec.limited_bound_parameters = opts.limited_bound_parameters;

  let adapter = write_adapter(schema, op);
  // the `fields` passed to upsertRow / transformForWrite / shouldUseOptimizedUpsertRow (config input)
  let fields_id = op["upserts"]
    .get(0)
    .or(op["transforms"].get(0))
    .or(op["shouldUse"].get(0))
    .and_then(|e| e["fieldsID"].as_i64());
  let op_fields = fields_id.and_then(|id| fields.get(&id)).cloned().unwrap_or_default();

  let s = |k: &str| args.get(k).as_str().map(str::to_string);
  let w = WriteArgs {
    table_name: s("tableName").unwrap_or_default(),
    collection_slug: s("collection").or_else(|| s("collectionSlug")),
    global_slug: s("globalSlug").or_else(|| s("global")),
    returning_false: matches!(args.get("returning"), JsVal::Bool(false)),
    now: recorded_now(op),
    ..Default::default()
  };
  let first_query = op["queries"].get(0).map(query_from).unwrap_or_default();
  let mut data = args.get("data").clone();
  let mut host = Host { st };
  let mut ops_host = Ops { st };
  let sch: payload_sql_upsert::sql::Schema<'_> = (&schema.raw).into();
  let ctx = WriteContext { adapter: &adapter, fields: &op_fields };
  let res = {
    let mut env = Env { exec: &mut exec, schema: sch, opts: &opts, ctx, host: &mut host };
    match method {
      "create" => ops::create(&mut env, &w, args.get("customID").clone(), &mut data),
      "createGlobal" => ops::create_global(&mut env, &w, args.get("slug").as_str().unwrap_or_default(), &mut data),
      "createVersion" | "createGlobalVersion" => {
        let v = CreateVersionArgs {
          autosave: args.get("autosave").clone(),
          created_at: args.get("createdAt").clone(),
          parent: args.get("parent").clone(),
          published_locale: args.get("publishedLocale").clone(),
          snapshot: args.get("snapshot").clone(),
          updated_at: args.get("updatedAt").clone(),
          version_data: args.get("versionData").clone(),
          drafts_enabled: op["draftsEnabled"].as_bool().unwrap_or(false),
        };
        if method == "createVersion" { ops::create_version(&mut env, &w, &v) } else { ops::create_global_version(&mut env, &w, &v) }
      }
      "updateOne" | "upsert" => {
        let options = args.get("options");
        let u = UpdateOneArgs {
          id: args.get("id").clone(),
          query: first_query,
          has_where_arg: args.get("hasWhere").truthy(),
          upsert: method == "upsert" || options.get("upsert").truthy(),
          atomic: options.get("atomic").is_true(),
        };
        ops::update_one(&mut env, &mut ops_host, &w, &u, &mut data)
      }
      "updateMany" => ops::update_many(&mut env, &mut ops_host, &w, &first_query, args.get("hasWhere").truthy(), args.get("limit"), &mut data),
      "updateGlobal" => ops::update_global(&mut env, &w, args.get("slug").as_str().unwrap_or_default(), &mut data),
      "updateVersion" | "updateGlobalVersion" => {
        let mut vd = args.get("versionData").clone();
        ops::update_version(&mut env, &w, args.get("id").clone(), first_query.where_.clone(), &mut vd)
      }
      "updateJobs" => {
        let mut w = w.clone();
        w.collection_slug = Some("payload-jobs".into());
        ops::update_jobs(&mut env, &mut ops_host, &w, args.get("id").clone(), &mut data)
      }
      "deleteOne" => ops::delete_one(env.exec, sch, &mut ops_host, &w, &first_query),
      "deleteMany" => ops::delete_many(env.exec, sch, &mut ops_host, &w, &first_query).map(|_| JsVal::Undefined),
      "deleteVersions" => ops::delete_versions(env.exec, sch, &mut ops_host, &w),
      other => Err(EngineError::internal(format!("unknown method {other}"))),
    }
  };
  (res, exec.statements.iter().map(|s| s.to_json()).collect())
}

fn is_write(sql: &str) -> bool {
  let t = sql.trim_start().to_ascii_lowercase();
  t.starts_with("insert") || t.starts_with("update") || t.starts_with("delete")
}

/// Compares errors: ValidationError by name + data.errors, others by name + message.
fn compare_error(ts: Option<&Json>, rs: Option<&EngineError>) -> Option<String> {
  match (ts, rs) {
    (None, None) => None,
    (Some(t), None) => Some(format!("TS threw {} but Rust succeeded", t["message"])),
    (None, Some(e)) => Some(format!("Rust threw {e} but TS succeeded")),
    (Some(t), Some(e)) => {
      let ts_name = t["name"].as_str().unwrap_or_default();
      if ts_name == "ValidationError" || e.name == "ValidationError" {
        let rs_errors = e.data.as_ref().and_then(|d| d.get("errors")).cloned().unwrap_or(Json::Null);
        let ts_errors = t["data"].get("errors").cloned().unwrap_or(Json::Null);
        if ts_name != e.name || ts_errors != rs_errors {
          return Some(format!("ValidationError mismatch: ts {ts_name} {ts_errors} rs {} {rs_errors}", e.name));
        }
        return None;
      }
      // drizzle errors surface as `DrizzleQueryError` (name `Error` in the engine model)
      let name_ok = ts_name == e.name || (ts_name == "DrizzleQueryError" && e.name == "Error");
      if !name_ok || t["message"].as_str() != Some(e.message.as_str()) {
        return Some(format!("error mismatch:\n  ts {ts_name}: {}\n  rs {}: {}", t["message"], e.name, e.message));
      }
      None
    }
  }
}

#[derive(Default)]
struct Stats {
  ops: usize,
  concurrent: usize,
  concurrent_mismatch: usize,
  replayed: usize,
  tables: Check,
  errors: Check,
  statements: Check,
  results: Check,
  transforms: Check,
  should_use: Check,
  upserts: Check,
  reads: Check,
  volatile_masked: usize,
  failures: Vec<String>,
}

fn is_iso_literal(v: &Json) -> bool {
  let s = v.as_str().unwrap_or("");
  s.len() == 26 && s.starts_with('\'') && s.ends_with("Z'") && s.as_bytes().get(11) == Some(&b'T')
}

/// Copies TS timestamp cells into the Rust dump where both sides hold ISO timestamps and differ.
fn mask_now_timestamps(got: &mut Dump, after: &Dump) -> bool {
  let mut masked = false;
  for (name, t) in got.iter_mut() {
    let Some(expected) = after.get(name) else { continue };
    if t["columns"] != expected["columns"] {
      continue;
    }
    let (Some(rows), Some(exp_rows)) = (t["rows"].as_array().cloned(), expected["rows"].as_array()) else { continue };
    if rows.len() != exp_rows.len() {
      continue;
    }
    let mut new_rows = rows.clone();
    for (r, (row, exp)) in rows.iter().zip(exp_rows).enumerate() {
      for (c, (cell, exp_cell)) in row.as_array().unwrap().iter().zip(exp.as_array().unwrap()).enumerate() {
        if cell != exp_cell && is_iso_literal(cell) && is_iso_literal(exp_cell) {
          new_rows[r][c] = exp_cell.clone();
          masked = true;
        }
      }
    }
    t["rows"] = Json::Array(new_rows);
  }
  masked
}

fn read_fixture(path: &Path) -> String {
  let out = std::process::Command::new("gzip").arg("-dc").arg(path).output().expect("gzip available");
  assert!(out.status.success(), "gzip -dc {} failed", path.display());
  String::from_utf8(out.stdout).expect("utf8 fixture")
}

fn replay_file(path: &Path, stats: &mut Stats) {
  let text = read_fixture(path);
  let mut schemas: HashMap<i64, (Schema, Connection)> = HashMap::new();
  let mut fields: HashMap<i64, JsVal> = HashMap::new();
  let mut prev_after: HashMap<i64, Dump> = HashMap::new();
  let mut rust_state: HashMap<i64, Dump> = HashMap::new();
  let suite = path.file_name().unwrap().to_string_lossy().trim_end_matches(".jsonl.gz").to_string();

  for line in text.lines() {
    let ev: Json = serde_json::from_str(line).unwrap();
    match ev["type"].as_str() {
      Some("schema") => {
        let id = ev["adapterID"].as_i64().unwrap();
        let schema = build_schema(&ev);
        let conn = open_db(&schema);
        schemas.insert(id, (schema, conn));
        prev_after.remove(&id);
        rust_state.remove(&id);
      }
      Some("fields") => {
        fields.insert(ev["fieldsID"].as_i64().unwrap(), decode(&ev["fields"]));
      }
      Some("op") => {
        stats.ops += 1;
        let adapter = ev["adapterID"].as_i64().unwrap();
        let concurrent = ev["concurrent"].as_bool().unwrap_or(false);
        let Some((schema, conn)) = schemas.get(&adapter) else { continue };
        // dumps are stored as per-table diffs: beforeDiff vs the previous op's after, afterDiff vs before
        let mut before = prev_after.get(&adapter).cloned().unwrap_or_default();
        apply_diff(&mut before, &ev["beforeDiff"]);
        let mut after = before.clone();
        apply_diff(&mut after, &ev["afterDiff"]);
        prev_after.insert(adapter, after.clone());
        if after.contains_key("$dumpError") || ev["args"].get("$encodeError").is_some() {
          continue;
        }
        if rust_state.get(&adapter) != Some(&before) {
          restore(conn, schema, &before);
        }

        let st = RefCell::new(State::new(&ev));
        let (result, statements) = run_op(conn, schema, &ev, &fields, &st);
        let got = dump(conn);
        rust_state.insert(adapter, got.clone());

        let label = format!("{suite}#{} {} {}", ev["seq"], ev["method"].as_str().unwrap_or(""), ev["args"]["tableName"]);
        let mut st = st.into_inner();
        let mut problems = std::mem::take(&mut st.problems);
        let mut s = Stats::default();

        // Columns filled by the drizzle `defaultNow` SQL default hold the wall-clock time of
        // execution; accept any ISO timestamp there.
        let mut got = got;
        let uses_now = statements.iter().any(|s| s["sql"].as_str().is_some_and(|q| q.contains("strftime('%Y-%m-%dT%H:%M:%fZ', 'now')")));
        if uses_now && got != after && mask_now_timestamps(&mut got, &after) {
          s.volatile_masked += 1;
        }
        let table_diff = (got != after).then(|| {
          let mut diff = vec![];
          for k in got.keys().chain(after.keys()).collect::<std::collections::BTreeSet<_>>() {
            if got.get(k) != after.get(k) {
              diff.push(format!("    {k}:\n      ts {}\n      rs {}", after.get(k).map(|v| v.to_string()).unwrap_or("-".into()), got.get(k).map(|v| v.to_string()).unwrap_or("-".into())));
            }
          }
          format!("\n{}", diff.join("\n"))
        });
        s.tables.add(&mut problems, "table contents differ", table_diff);
        let ts_error = ev.get("error").filter(|e| !e.is_null());
        s.errors.add(&mut problems, "error", compare_error(ts_error, result.as_ref().err()));
        if let (Ok(r), None) = (&result, ts_error) {
          s.results.add(&mut problems, "result", first_diff(&encode_value(r), &ev["result"], "result"));
        }
        let ts_writes: Vec<&Json> = ev["statements"].as_array().map(|a| a.iter().filter(|s| is_write(s["sql"].as_str().unwrap_or(""))).collect()).unwrap_or_default();
        let rs_writes: Vec<&Json> = statements.iter().filter(|s| is_write(s["sql"].as_str().unwrap_or(""))).collect();
        let stmt_diff = (ts_writes != rs_writes).then(|| {
          format!("\n  ts {}\n  rs {}", serde_json::to_string(&ts_writes).unwrap(), serde_json::to_string(&rs_writes).unwrap())
        });
        s.statements.add(&mut problems, "write statements differ", stmt_diff);
        for (left, what) in [
          (st.transforms.len(), "transformForWrite"),
          (st.should_use.len(), "shouldUseOptimizedUpsertRow"),
          (st.upserts.len(), "upsertRow"),
          (st.reads.len(), "read transform"),
        ] {
          if left > 0 && ts_error.is_none() {
            problems.push(format!("{left} recorded {what} calls not made by Rust"));
          }
        }
        s.transforms = st.transform_check;
        s.should_use = st.should_use_check;
        s.upserts = st.upsert_check;
        s.reads = st.read_check;

        if concurrent {
          stats.concurrent += 1;
          if !problems.is_empty() {
            stats.concurrent_mismatch += 1;
            if std::env::var("UPSERT_SHOW_CONCURRENT").is_ok() {
              eprintln!("CONCURRENT {label}\n  {}\n", problems.join("\n  "));
            }
          }
          // concurrent recordings interleave with other operations' writes; not asserted
          continue;
        }
        stats.replayed += 1;
        for (dst, src) in [
          (&mut stats.tables, s.tables),
          (&mut stats.errors, s.errors),
          (&mut stats.statements, s.statements),
          (&mut stats.results, s.results),
          (&mut stats.transforms, s.transforms),
          (&mut stats.should_use, s.should_use),
          (&mut stats.upserts, s.upserts),
          (&mut stats.reads, s.reads),
        ] {
          dst.merge(src);
        }
        stats.volatile_masked += s.volatile_masked;
        if !problems.is_empty() {
          stats.failures.push(format!("{label}\n  {}", problems.join("\n  ")));
        }
      }
      _ => {}
    }
  }
}

fn fmt(c: Check) -> String {
  format!("{}/{}", c.matched, c.checked)
}

#[test]
fn replay_recorded_operations() {
  let dir = std::env::var("UPSERT_FIXTURES")
    .map(PathBuf::from)
    .unwrap_or_else(|_| PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../test/__rs/upsert/fixtures"));
  let filter = std::env::var("UPSERT_FIXTURE").ok();
  let mut files: Vec<PathBuf> = std::fs::read_dir(&dir)
    .map(|d| d.filter_map(|e| e.ok().map(|e| e.path())).filter(|p| p.to_string_lossy().ends_with(".jsonl.gz")).collect())
    .unwrap_or_default();
  files.retain(|p| filter.as_ref().is_none_or(|f| p.to_string_lossy().contains(f.as_str())));
  files.sort();
  assert!(!files.is_empty(), "no fixtures in {} (run test/__rs/upsert/record.sh)", dir.display());
  let mut total = Stats::default();
  let max_failures = std::env::var("UPSERT_MAX_FAILURES").ok().and_then(|v| v.parse().ok()).unwrap_or(5);
  for f in &files {
    let mut s = Stats::default();
    replay_file(f, &mut s);
    eprintln!(
      "{}: ops {} alone {} (concurrent {} of which differing {}; defaultNow-masked {}) tables {} errors {} results {} write-statements {} transformForWrite {} shouldUse {} upsertRow {} reads {}",
      f.file_name().unwrap().to_string_lossy(),
      s.ops,
      s.replayed,
      s.concurrent,
      s.concurrent_mismatch,
      s.volatile_masked,
      fmt(s.tables),
      fmt(s.errors),
      fmt(s.results),
      fmt(s.statements),
      fmt(s.transforms),
      fmt(s.should_use),
      fmt(s.upserts),
      fmt(s.reads),
    );
    for fail in s.failures.iter().take(max_failures) {
      eprintln!("FAIL {fail}\n");
    }
    total.ops += s.ops;
    total.replayed += s.replayed;
    total.concurrent += s.concurrent;
    total.concurrent_mismatch += s.concurrent_mismatch;
    for (dst, src) in [
      (&mut total.tables, s.tables),
      (&mut total.errors, s.errors),
      (&mut total.statements, s.statements),
      (&mut total.results, s.results),
      (&mut total.transforms, s.transforms),
      (&mut total.should_use, s.should_use),
      (&mut total.upserts, s.upserts),
      (&mut total.reads, s.reads),
    ] {
      dst.merge(src);
    }
    total.failures.extend(s.failures);
  }
  eprintln!(
    "TOTAL: ops {} alone {} (concurrent {}, differing {}) tables {} errors {} results {} write-statements {} transformForWrite {} shouldUse {} upsertRow {} reads {}",
    total.ops,
    total.replayed,
    total.concurrent,
    total.concurrent_mismatch,
    fmt(total.tables),
    fmt(total.errors),
    fmt(total.results),
    fmt(total.statements),
    fmt(total.transforms),
    fmt(total.should_use),
    fmt(total.upserts),
    fmt(total.reads),
  );
  assert!(total.replayed > 0, "replayed zero recorded operations");
  assert!(total.failures.is_empty(), "{} of {} replayed operations differ", total.failures.len(), total.replayed);
}
